import torch


def gen_inputs(ctx, device):
    import torch
    shape = ctx["x__shape"]
    dtype = getattr(torch, ctx["x__dtype"])
    # Positive domain [0.05, 2.0): spans the small-positive (reflection),
    # mid (recurrence) and large (asymptotic) paths exercised by the pytest,
    # while avoiding non-positive-integer poles / catastrophic cancellation.
    x = torch.rand(shape, dtype=dtype, device=device) * 1.95 + 0.05
    return {"x": x}


def run(x):
    return torch.special.digamma(x)
